class Node:
    def __init__(self, v, l=None, r=None):
        self.v, self.l, self.r = v, l, r

def height(n):
    if n is None:
        return 0
    return 1 + max(height(n.l), height(n.r))

tree = Node(1, Node(2, Node(4)), Node(3))
print(height(tree))

def inorder(n):
    if n is None:
        return []
    return inorder(n.l) + inorder(n.r) + [n.v]
